// native_motion_register.cpp — registers every native of native_motion_decl.h with
// bronze (embed::registerNative) under __bro_native.motion. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_motion from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.motion.<Class>Proto for motion.js to chain.

#include "native_motion_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

bool ctor(const char* path, void* f, ev::HandleDestructor dtor, bronze::runtime::Finalize finalize,
          std::initializer_list<const char*> params, std::string* error) {
    ev::NativeSignature s = sig(path, params, ev::NativeKind::Constructor);
    s.className = path;
    s.destructor = dtor;
    s.finalize = finalize;
    return ev::registerNative(path, f, s, error);
}

// The prototype every instance of a class is born on, published where the
// wrapper reads it. Skipped when the roots are not there (bro-native-manifest
// registers without them; the manifest does not need the prototype).
void publishPrototype(const char* ns, const char* className, const char* protoName) {
    ev::GlobalValue root = ev::globalValue("__bro_native");
    if (!root.found || !ev::isObject(root.value)) return;
    ev::GlobalValue proto = ev::nativeClassPrototype(className);
    if (!proto.found) return;
    // Each value rooted before the next allocating call (bronze embed GC contract).
    ev::Persistent rootSlot(root.value);
    ev::Persistent protoSlot(proto.value);
    ev::Persistent nsSlot(ev::getProperty(rootSlot.get(), ns));
    if (!ev::isObject(nsSlot.get())) return;
    ev::setProperty(nsSlot.get(), protoName, protoSlot.get());
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_motion(std::string* error) {
    bool ok =
        ctor("__bro_native.motion.ArdyMotionPipeline", p(&bro_motion_ArdyMotionPipeline_ctor), &bro_motion_ArdyMotionPipeline_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_device_get", p(&bro_motion_ArdyMotionPipeline_device_get), "str", {"__bro_native.motion.ArdyMotionPipeline"}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate", p(&bro_motion_ArdyMotionPipeline_generate), "void", {"__bro_native.motion.ArdyMotionPipeline", "str", "i32", "i32", "f64", "i32", "f64"}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate_frames", p(&bro_motion_ArdyMotionPipeline_generate_frames), "i32", {}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate_joints", p(&bro_motion_ArdyMotionPipeline_generate_joints), "i32", {}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate_fps", p(&bro_motion_ArdyMotionPipeline_generate_fps), "f64", {}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate_positions", p(&bro_motion_ArdyMotionPipeline_generate_positions), "f32[]", {}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate_parents", p(&bro_motion_ArdyMotionPipeline_generate_parents), "i32[]", {}, error) &&
        fn("__bro_native.motion.ArdyMotionPipeline_generate_footContacts", p(&bro_motion_ArdyMotionPipeline_generate_footContacts), "f32[]", {}, error);
#if BRO_WITH_DIFFUSION && BRO_WITH_LM
    ok = ok &&
        fn("__bro_native.motion.init", p(&bro_motion_init), "void", {}, error) &&
        fn("__bro_native.motion.load", p(&bro_motion_load), "__bro_native.motion.ArdyMotionPipeline", {"bool", "str", "bool", "str", "bool", "str"}, error);
#endif
    if (!ok) return false;
    publishPrototype("motion", "__bro_native.motion.ArdyMotionPipeline", "ArdyMotionPipelineProto");
    return true;
}

}  // namespace bro::bronze_host
